import java.nio.*;import java.nio.file.*;import java.util.*;import com.google.gson.*;import org.lwjgl.glfw.GLFW;import org.lwjgl.opengl.*;import com.iridium126.createmanaindustry.client.particles.engine.hardware.*;
/** Full variable-Q contiguous geometry, independent cache per comparison side; not complete physics/FPS. */
public final class R8SequenceGpu extends ModelPopulationGpuValidation{
 record Cell(int x,int y,int z){}record Mode(String name,int backend,int policy,int period){}
 static final Mode BASE=new Mode("aabb",1,0,1);static final Mode[] MODES={new Mode("merged",1,1,1),new Mode("event",1,2,1),new Mode("paged",1,4,1),new Mode("unsorted",1,8,1),new Mode("combined",1,7,1),new Mode("triangle-paged",2,4,1),new Mode("cuda-paged",0,4,1),new Mode("rebuild4",1,0,4),new Mode("rebuild8",1,0,8),new Mode("triangle-rebuild4",2,0,4),new Mode("triangle-rebuild8",2,0,8),new Mode("rt-vs-cuda-paged",1,4,1),new Mode("triangle-vs-cuda-paged",2,4,1),new Mode("paged-unsorted",1,12,1),new Mode("combined-unsorted",1,15,1)};
 static final List<Object> initialization=new ArrayList<>();static Path out,source;static JsonObject deps;static ByteBuffer[] packets,points,requests,owners;static int[] ns,qs,sceneFrames;static float cellSize;static int phase;
 static ByteBuffer payload(Path root,JsonObject frame,String key)throws Exception{byte[] data=Files.readAllBytes(root.resolve(frame.get(key).getAsString()));check(HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(data)).equals(frame.get(key.equals("file")?"sha256":key+"_sha256").getAsString()),"payload SHA");return bytes(data.length).put(data).flip();}
 static int align(int n){return(n+255)&~255;}
 static Mode baseline(Mode mode){if(mode.name.endsWith("vs-cuda-paged"))return new Mode("cuda-paged-control",0,4,1);return new Mode("same-backend-two-pass",mode.backend,0,1);}
 static int[][] reference(int frame){int n=ns[frame],q=qs[frame];var grid=new HashMap<Cell,ArrayList<Integer>>();var p=points[frame];for(int i=0;i<n;i++){Cell k=new Cell((int)Math.floor(p.getFloat(i*16)/cellSize),(int)Math.floor(p.getFloat(i*16+4)/cellSize),(int)Math.floor(p.getFloat(i*16+8)/cellSize));grid.computeIfAbsent(k,a->new ArrayList<>()).add(i);}int[][] result=new int[q][];var r=requests[frame];for(int i=0;i<q;i++){float x=r.getFloat(i*16),y=r.getFloat(i*16+4),z=r.getFloat(i*16+8),radius=r.getFloat(i*16+12);int cx=(int)Math.floor(x/cellSize),cy=(int)Math.floor(y/cellSize),cz=(int)Math.floor(z/cellSize),owner=owners[frame].getInt(i*4);var found=new ArrayList<Integer>();for(int a=-1;a<=1;a++)for(int b=-1;b<=1;b++)for(int c=-1;c<=1;c++){var list=grid.get(new Cell(cx+a,cy+b,cz+c));if(list==null)continue;for(int j:list){if(j==owner)continue;float dx=x-p.getFloat(j*16),dy=y-p.getFloat(j*16+4),dz=z-p.getFloat(j*16+8);if((dx*dx+dy*dy)+dz*dz<=radius*radius)found.add(j);}}result[i]=found.stream().mapToInt(xi->xi).sorted().toArray();}return result;}
 static class Runner implements AutoCloseable{
  long bridge,worker,nonce;boolean first=true;final Mode mode;final int timer=GL15.glGenQueries();Runner(Mode mode)throws Exception{this.mode=mode;long began=System.nanoTime();bridge=HardwareNative.createCopy(16<<20,1);try{worker=HardwareNative.createAsyncQueryForBackend(bridge,131072,262144,4_194_000,71,mode.backend,deps.getAsJsonObject("cuda_cudart").get("root").getAsString(),deps.getAsJsonObject("optix").get("root").getAsString(),source.toAbsolutePath().toString(),deps.getAsJsonObject("cuda_nvcc").get("root").getAsString());HardwareNative.configureAsyncQuery(worker,mode.policy,64<<20);}catch(Throwable e){close();throw e;}initialization.add(Map.of("mode",mode.name,"backend",mode.backend,"policy",mode.policy,"initialization_cpu_ms",(System.nanoTime()-began)/1e6,"owned_memory",HardwareNative.probe()));}
  double[] run(int f,int[][] expected)throws Exception{var buffers=HardwareNative.copyBuffers(bridge,0);GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,buffers[0]);GL15.glBufferSubData(GL43.GL_SHADER_STORAGE_BUFFER,0,packets[f].duplicate().order(ByteOrder.nativeOrder()).putLong(8,++nonce));GL15.glBeginQuery(GL33.GL_TIME_ELAPSED,timer);long start=System.nanoTime();check(HardwareNative.submitAsyncQuery(worker,0,nonce,mode.backend,f!=0&&sceneFrames[f]%mode.period!=0),"submit");int state;long deadline=System.nanoTime()+10_000_000_000L;do{if(Boolean.getBoolean("cmi.r8.consumerStrategyWait")){state=HardwareNative.pollAsyncQuery(worker,0,nonce);if(state==1){if((mode.policy&2)!=0)HardwareNative.waitAsyncQuery(worker,0,nonce,50);else java.util.concurrent.locks.LockSupport.parkNanos(50_000);}}else state=HardwareNative.waitAsyncQuery(worker,0,nonce,50);check(System.nanoTime()<deadline,"bounded wait");}while(state==1);check(state==2,"complete result "+mode.name+" f="+f+" "+HardwareNative.asyncQueryError(worker,0,nonce));HardwareNative.consumeAsyncQuery(worker,0,nonce);GL15.glEndQuery(GL33.GL_TIME_ELAPSED);double gpu=GL33.glGetQueryObjectui64(timer,GL15.GL_QUERY_RESULT)/1e6;var stats=HardwareNative.asyncQueryStats(worker,0,nonce);double[] nativeTime=HardwareNative.asyncQueryTiming(worker,0,nonce);double[] trace=HardwareNative.asyncQueryTrace(worker,0,nonce);if(expected!=null){var data=R7HardwareGpu.readShared(buffers[1],64+align(16+(qs[f]+1)*8)+Math.toIntExact(stats[7])*4);int ids=data.getInt(24);long total=0;for(int row=0;row<expected.length;row++){long from=data.getLong(80+row*8),to=data.getLong(88+row*8);check(from==total&&to>=from&&to<=stats[3],"CSR bounds");int[] actual=new int[(int)(to-from)];for(int k=0;k<actual.length;k++)actual[k]=data.getInt((ids+(int)from+k)*4);Arrays.sort(actual);check(Arrays.equals(actual,expected[row]),"full actual candidate row "+row);total=to;}check(total==stats[7],"actual NNZ counter");}long fence=GL32.glFenceSync(GL32.GL_SYNC_GPU_COMMANDS_COMPLETE,0);GL11.glFlush();while(!HardwareNative.recycleAsyncQuery(worker,0,nonce,fence)){check(System.nanoTime()<deadline,"retirement");Thread.onSpinWait();}GL32.glDeleteSync(fence);trace=HardwareNative.asyncQueryTrace(worker,0,nonce);double[] result={gpu,(System.nanoTime()-start)/1e6,nativeTime[0],nativeTime[1],nativeTime[3],nativeTime[4],nativeTime[6],stats[7],stats[8],nativeTime[2],nativeTime[5],trace[13],trace[14],trace[15],trace[2],trace[3],trace[4],trace[5],trace[6],trace[7],trace[8],trace[9]};if(first){initialization.add(Map.of("mode",mode.name,"first_execution",result));first=false;}return result;}
  public void close(){if(worker!=0){long end=System.nanoTime()+10_000_000_000L;while(!HardwareNative.closeAsyncQuery(worker)){check(System.nanoTime()<end,"close");java.util.concurrent.locks.LockSupport.parkNanos(100_000);}worker=0;}if(bridge!=0)HardwareNative.closeCopy(bridge);bridge=0;GL15.glDeleteQueries(timer);}
 }
 public static void main(String[] args)throws Exception{
  out=Path.of(System.getProperty("cmi.benchmark.output"));Files.createDirectories(out);check(!Files.exists(out.resolve("samples.csv")),"fresh run");Path input=Path.of(System.getProperty("cmi.r8.sequence"));var m=JsonParser.parseString(Files.readString(input.resolve("inputs.json"))).getAsJsonObject();check(m.get("schema").getAsInt()==2&&m.get("per_frame_queries").getAsBoolean()&&m.get("periodic_rebuild_eligible").getAsBoolean(),"full contiguous stable topology");phase=m.get("stage").getAsString().equals("ordinary")?1:2;var fs=m.getAsJsonArray("frames");int count=fs.size();check(count==64,"all 64 frames");packets=new ByteBuffer[count];points=new ByteBuffer[count];requests=new ByteBuffer[count];owners=new ByteBuffer[count];ns=new int[count];qs=new int[count];sceneFrames=new int[count];cellSize=Math.max(.000001f,m.get("max_radius").getAsFloat());
  for(int f=0;f<count;f++){var r=fs.get(f).getAsJsonObject();sceneFrames[f]=r.get("scene_frame").getAsInt();ns[f]=r.get("points").getAsInt();qs[f]=r.get("queries").getAsInt();points[f]=payload(input,r,"file");requests[f]=payload(input,r,"requests");owners[f]=payload(input,r,"owners");int n=ns[f],q=qs[f],ro=align(64+n*16),oo=align(ro+q*16),map=align(oo+q*4);float bound=.000001f;for(int j=0;j<q;j++)bound=Math.max(bound,requests[f].getFloat(j*16+12));var p=bytes(map+n*4);p.putInt(0,0x52374931).putInt(4,phase).putInt(16,n).putInt(20,q).putInt(24,1).putFloat(28,bound).putInt(32,64).putInt(36,ro).putInt(40,oo).putInt(44,map).putInt(48,n).putLong(56,71);p.position(64);p.put(points[f].duplicate());p.position(ro);p.put(requests[f].duplicate());p.position(oo);p.put(owners[f].duplicate());for(int i=0;i<n;i++)p.putInt(map+i*4,i);p.clear();packets[f]=p;}
  source=out.resolve("source");Files.createDirectory(source);for(String name:List.of("Query.h","grid.cu","rt.cu","rt-triangle.cu","tensor.cu"))Files.copy(Path.of("native/offload",name),source.resolve(name));deps=JsonParser.parseString(Files.readString(Path.of(".gradle/neighbor-rt/dependencies.json"))).getAsJsonObject();GLFW.glfwInit();GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,4);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,6);long w=GLFW.glfwCreateWindow(32,32,"R8 full sequence",0,0);check(w!=0,"context");GLFW.glfwMakeContextCurrent(w);GL.createCapabilities();HardwareNative.load(Path.of(".gradle/hardware-offload/build"));var result=new LinkedHashMap<String,Object>();result.put("passed",false);result.put("scope","all variable-Q actual sequence geometry and shared handoff; fixture upload excluded equally, no full physics/FPS");result.put("consumer_wait",Boolean.getBoolean("cmi.r8.consumerStrategyWait")?"strategy: legacy poll/park versus native nonce event":"common native event wait for geometry isolation; event mode is a negative control");result.put("process_id",ProcessHandle.current().pid());result.put("input_manifest",m);var modes=Arrays.stream(MODES).filter(x->Set.of(System.getProperty("cmi.r8.paths","merged,event,paged,unsorted,combined,triangle-paged,cuda-paged,rebuild4,rebuild8,triangle-rebuild4,triangle-rebuild8,rt-vs-cuda-paged,triangle-vs-cuda-paged").split(",")).contains(x.name)).toList();
  check(!modes.isEmpty(),"at least one known R8 candidate required");
  int[][][] truth=new int[count][][];try(var csv=Files.newBufferedWriter(out.resolve("samples.csv"))){csv.write("candidate,comparison,pair,side,frame,queries,gpu_ms,cpu_ms,native_gpu_ms,worker_ms,maintenance_ms,query_ms,materialize_ms,nnz,pages,descriptor_ms,scan_ms,sort_ms,seal_ms,signal_ms,queued_worker_ms,queued_input_validated_ms,queued_query_submitted_or_ready_ms,queued_output_ms,queued_notification_ms,queued_consumed_ms,queued_retire_begin_ms,queued_retired_ms\n");for(var mode:modes){for(int comp=0;comp<3;comp++){Mode control=baseline(mode);Mode a=comp==1?mode:control,b=comp==0?control:mode;String label=comp==0?"AA_base":comp==1?"AA_candidate":"AB";try(var ra=new Runner(a);var rb=new Runner(b)){for(int f=0;f<count;f++){int[][] expected=comp==2?(truth[f]==null?(truth[f]=reference(f)):truth[f]):null;ra.run(f,expected);rb.run(f,expected);}for(int f=0;f<count;f++)for(int turn=0;turn<2;turn++){int side=(f+turn)&1;double[] times=(side==0?ra:rb).run(f,null);csv.write(mode.name+","+label+","+f+","+side+","+f+","+qs[f]);for(double x:times)csv.write(","+x);csv.write("\n");}csv.flush();}System.out.println("R8 sequence "+mode.name+" "+label);}}check(GL11.glGetError()==0,"final sequence GL state");result.put("passed",true);}finally{result.put("checks",checks);result.put("initialization_and_first_execution",initialization);Files.writeString(out.resolve("sequence.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result)+"\n");GLFW.glfwDestroyWindow(w);GLFW.glfwTerminate();}
 }
}
